parameters.jsCode:
// Parse the AI's JSON reply safely. On any failure, fall back to the
// CONFIG fallback message and flag a human — never send raw model
// output or an error to the customer.
const first = $input.first().json;
let raw = '';
try { raw = first.choices[0].message.content; } catch (e) { raw = ''; }
let parsed = null;
try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }
const cfg = $('CONFIG — Edit Me').first().json;
const norm = $('Normalise Message').first().json;
if (!parsed || typeof parsed.reply !== 'string' || !parsed.reply.trim()) {
  return [{ json: {
    reply: cfg.config_fallback_message,
    needs_human: true,
    is_lead: false,
    parse_failed: true,
    sender_phone: norm.sender_phone,
    sender_name: norm.sender_name,
    message_text: norm.message_text
  }}];
}
return [{ json: {
  reply: parsed.reply,
  needs_human: !!parsed.needs_human,
  is_lead: !!parsed.is_lead,
  parse_failed: false,
  sender_phone: norm.sender_phone,
  sender_name: norm.sender_name,
  message_text: norm.message_text
}}];

